-- =========================================================
-- 知微教学平台 · 教学就绪 初始化 SQL (v0.7 骨架数据)
-- 生成自 p_primary_all / p0_* / textbook_versions 等数据模块
-- 说明：课标叶子条款(tb_standard_clause) 待 PDF OCR 后回填
-- =========================================================
SET NAMES utf8mb4;
DROP TABLE IF EXISTS tb_version_standard_map;
DROP TABLE IF EXISTS tb_kg_edge;
DROP TABLE IF EXISTS tb_kg_node;
DROP TABLE IF EXISTS school_textbook_binding;
DROP TABLE IF EXISTS tb_standard_clause;
DROP TABLE IF EXISTS tb_textbook_version;

CREATE TABLE tb_textbook_version (
  id            BIGINT        PRIMARY KEY AUTO_INCREMENT,
  version_key   VARCHAR(64)   NOT NULL COMMENT '唯一标识: 学段_学科_版本标识_年级_册别',
  xue_duan      VARCHAR(8)    NOT NULL COMMENT '学段:小学/初中/高中',
  nian_ji       VARCHAR(8)    NOT NULL COMMENT '年级',
  xue_ke        VARCHAR(16)   NOT NULL COMMENT '学科',
  jiao_cai_ming VARCHAR(96)   NOT NULL COMMENT '教材名称',
  chu_ban_she   VARCHAR(32)   NOT NULL COMMENT '出版社全称',
  ban_ben_biao_shi VARCHAR(32) NOT NULL COMMENT '版本标识',
  ce_bie        VARCHAR(8)    NOT NULL COMMENT '册别:上册/下册/全一册',
  mu_lu_url     VARCHAR(512)  COMMENT '教材目录页URL',
  UNIQUE KEY uk_version (version_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='教材版本';

CREATE TABLE tb_version_standard_map (
  id            BIGINT        PRIMARY KEY AUTO_INCREMENT,
  version_id    BIGINT        NOT NULL COMMENT '教材版本ID',
  version_key   VARCHAR(64)   NOT NULL,
  dan_yuan      VARCHAR(96)   NOT NULL COMMENT '单元名称',
  ke_biao_tiao_mu VARCHAR(255) NOT NULL COMMENT '课标条目(官方结构路径)',
  pi_pei_du     VARCHAR(16)   NOT NULL COMMENT '匹配度:完全匹配/部分匹配',
  zhi_shi_dian  JSON          COMMENT '知识点名称列表',
  KEY idx_vk (version_key),
  CONSTRAINT fk_vsm_version FOREIGN KEY (version_id) REFERENCES tb_textbook_version(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='教材版本-课标映射';

CREATE TABLE tb_kg_node (
  id            BIGINT        PRIMARY KEY AUTO_INCREMENT,
  node_key      VARCHAR(512)  NOT NULL COMMENT '业务键: version_key|路径',
  version_key   VARCHAR(64)   NOT NULL,
  dan_yuan      VARCHAR(96)   COMMENT '所属单元',
  parent_id     BIGINT        COMMENT '父节点ID (单元节点parent为NULL)',
  ming_cheng    VARCHAR(160)  NOT NULL COMMENT '知识点名称',
  level         TINYINT       NOT NULL COMMENT '层级 2单元/3知识点/4子知识点...',
  qian_zhi      JSON          COMMENT '前置知识点名称列表',
  nan_du        VARCHAR(4)    COMMENT '难度等级 L1-L4',
  neng_li_wei_du VARCHAR(32)  COMMENT '能力维度',
  UNIQUE KEY uk_node (node_key),
  KEY idx_kg_vk (version_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='知识图谱节点';

CREATE TABLE tb_kg_edge (
  id            BIGINT        PRIMARY KEY AUTO_INCREMENT,
  from_node_id  BIGINT        NOT NULL COMMENT '前置/父节点',
  to_node_id    BIGINT        NOT NULL COMMENT '后继/子节点',
  relation_type VARCHAR(16)   NOT NULL COMMENT 'belong(归属)/prereq(前置)',
  CONSTRAINT fk_edge_from FOREIGN KEY (from_node_id) REFERENCES tb_kg_node(id),
  CONSTRAINT fk_edge_to   FOREIGN KEY (to_node_id)   REFERENCES tb_kg_node(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='知识图谱边';

CREATE TABLE tb_standard_clause (
  id            BIGINT        PRIMARY KEY AUTO_INCREMENT,
  xue_duan      VARCHAR(8)    NOT NULL,
  xue_ke        VARCHAR(16)   NOT NULL,
  tiao_mu_lu_jing VARCHAR(255) NOT NULL COMMENT '课标条目官方结构路径',
  ye_zi_bian_hao VARCHAR(32)  COMMENT '叶子条款号 如 3.2.1',
  zheng_wen      TEXT         COMMENT '条款正文(待PDF OCR回填)',
  UNIQUE KEY uk_clause (xue_duan,xue_ke,tiao_mu_lu_jing,ye_zi_bian_hao)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='课标条款(叶子级,待PDF OCR回填)';

CREATE TABLE school_textbook_binding (
  id            BIGINT        PRIMARY KEY AUTO_INCREMENT,
  school_id     BIGINT        NOT NULL,
  version_key   VARCHAR(64)   NOT NULL,
  sheng_xiao_xue_nian VARCHAR(16) COMMENT '生效学年',
  UNIQUE KEY uk_bind (school_id, version_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='学校-教材绑定(运行期写入)';

